#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <algorithm>
#include <climits>
#include <string>
using namespace std;

const int MAX_SIZE = 20;
const int MAX_NOD = 400;
const int MAX_EDG = 200000;
const int INF = 199999999;

int grid[MAX_SIZE][MAX_SIZE];
int spfa_dist[MAX_NOD];
int spfa_queue[MAX_NOD];
int in_spfa[MAX_NOD];
int all_dist[MAX_NOD][MAX_NOD];
int n_nodes, N, TIME_LIMIT;
string current_line;
int zr, zc;
int dr[4] = {0, 0, -1, 1};
int dc[4] = {-1, 1, 0, 0};

struct FlowEdge {
    int src, dst, cap, next;
};

FlowEdge edges[MAX_EDG];
int edge_head[MAX_NOD];
int edge_count;
int source_node, sink_node;
vector<int> sources, destinations;

int to_id(int r, int c) { return (r - 1) * N + c; }

bool is_valid(int r, int c) {
    return r >= 1 && r <= N && c >= 1 && c <= N && grid[r][c] != -1;
}

void construct_adjacency() {
    n_nodes = N * N;
    memset(all_dist, -1, sizeof(all_dist));
    for (int r = 1; r <= N; ++r) {
        for (int c = 1; c <= N; ++c) {
            if (grid[r][c] == -1) continue;
            int u = to_id(r, c);
            all_dist[u][u] = 0;
            for (int d = 0; d < 4; ++d) {
                int nr = r + dr[d], nc = c + dc[d];
                if (is_valid(nr, nc)) {
                    int v = to_id(nr, nc);
                    all_dist[u][v] = 1;
                }
            }
        }
    }
}

void spfa_compute() {
    for (int i = 1; i <= n_nodes; ++i) spfa_dist[i] = INF;
    int head = 0, tail = 0;
    int start = to_id(zr, zc);
    spfa_dist[start] = 0;
    spfa_queue[tail++] = start;
    while (head < tail) {
        int u = spfa_queue[head++];
        for (int v = 1; v <= n_nodes; ++v) {
            if (all_dist[u][v] == 1 && spfa_dist[v] > spfa_dist[u] + 1) {
                spfa_dist[v] = spfa_dist[u] + 1;
                spfa_queue[tail++] = v;
            }
        }
    }
}

void floyd_warshall() {
    for (int k = 1; k <= n_nodes; ++k) {
        for (int i = 1; i <= n_nodes; ++i) {
            for (int j = 1; j <= n_nodes; ++j) {
                if (all_dist[i][k] != -1 && all_dist[k][j] != -1) {
                    if (all_dist[i][j] == -1 || all_dist[i][j] > all_dist[i][k] + all_dist[k][j]) {
                        all_dist[i][j] = all_dist[i][k] + all_dist[k][j];
                    }
                }
            }
        }
    }
}

void initialize_flow_network() {
    memset(edge_head, -1, sizeof(edge_head));
    edge_count = 0;
    source_node = 0;
    sink_node = sources.size() + destinations.size() + 1;

    for (size_t i = 0; i < sources.size(); i += 3) {
        int cnt = sources[i + 2];
        edges[edge_count] = {source_node, (int)(i/3)+1, cnt, edge_head[source_node]};
        edge_head[source_node] = edge_count++;
        edges[edge_count] = {(int)(i/3)+1, source_node, 0, edge_head[(int)(i/3)+1]};
        edge_head[(int)(i/3)+1] = edge_count++;
    }

    for (size_t i = 0; i < destinations.size(); i += 3) {
        int cnt = destinations[i + 2];
        edges[edge_count] = {(int)(sources.size()/3) + (int)(i/3) + 1, sink_node, cnt, edge_head[(int)(sources.size()/3) + (int)(i/3) + 1]};
        edge_head[(int)(sources.size()/3) + (int)(i/3) + 1] = edge_count++;
        edges[edge_count] = {sink_node, (int)(sources.size()/3) + (int)(i/3) + 1, 0, edge_head[sink_node]};
        edge_head[sink_node] = edge_count++;
    }

    int src_pos = to_id(zr, zc);
    for (size_t i = 0; i < sources.size(); i += 3) {
        int sr = sources[i], sc = sources[i + 1];
        int sp = to_id(sr, sc);
        for (size_t j = 0; j < destinations.size(); j += 3) {
            int dr = destinations[j], dc = destinations[j + 1];
            int dp = to_id(dr, dc);
            if (all_dist[sp][dp] != -1 && all_dist[sp][dp] <= TIME_LIMIT) {
                if (all_dist[sp][dp] < spfa_dist[dp]) {
                    edges[edge_count] = {(int)(i/3)+1, (int)(sources.size()/3) + (int)(j/3) + 1, INF, edge_head[(int)(i/3)+1]};
                    edge_head[(int)(i/3)+1] = edge_count++;
                    edges[edge_count] = {(int)(sources.size()/3) + (int)(j/3) + 1, (int)(i/3)+1, 0, edge_head[(int)(sources.size()/3) + (int)(j/3) + 1]};
                    edge_head[(int)(sources.size()/3) + (int)(j/3) + 1] = edge_count++;
                } else if (all_dist[sp][dp] == spfa_dist[dp]) {
                    for (int d = 0; d < 4; ++d) {
                        int nr = dr + dr[d], nc = dc + dc[d];
                        if (is_valid(nr, nc)) {
                            int np = to_id(nr, nc);
                            if (all_dist[sp][np] == all_dist[sp][dp] - 1 && all_dist[sp][np] < spfa_dist[np]) {
                                edges[edge_count] = {(int)(i/3)+1, (int)(sources.size()/3) + (int)(j/3) + 1, INF, edge_head[(int)(i/3)+1]};
                                edge_head[(int)(i/3)+1] = edge_count++;
                                edges[edge_count] = {(int)(sources.size()/3) + (int)(j/3) + 1, (int)(i/3)+1, 0, edge_head[(int)(sources.size()/3) + (int)(j/3) + 1]};
                                edge_head[(int)(sources.size()/3) + (int)(j/3) + 1] = edge_count++;
                            }
                        }
                    }
                }
            }
        }
    }
}

int level[MAX_NOD];
int q_bfs[MAX_NOD];

bool bfs_flow() {
    memset(level, -1, sizeof(level));
    int f = 0, r = 0;
    q_bfs[r++] = source_node;
    level[source_node] = 0;
    while (f < r) {
        int u = q_bfs[f++];
        for (int e = edge_head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].dst;
            if (level[v] == -1 && edges[e].cap > 0) {
                level[v] = level[u] + 1;
                if (v == sink_node) return true;
                q_bfs[r++] = v;
            }
        }
    }
    return false;
}

int dfs_flow(int u, int flow) {
    if (u == sink_node) return flow;
    for (int &e = edge_head[u]; e != -1; e = edges[e].next) {
        int v = edges[e].dst;
        if (level[v] == level[u] + 1 && edges[e].cap > 0) {
            int f = dfs_flow(v, min(flow, edges[e].cap));
            if (f > 0) {
                edges[e].cap -= f;
                edges[e^1].cap += f;
                return f;
            }
        }
    }
    return 0;
}

int dinic_maxflow() {
    int flow = 0;
    while (bfs_flow()) {
        for (int i = 0; i <= sink_node; ++i) edge_head[i] = -1;
        memcpy(edge_head, edge_head, sizeof(edge_head));
        int f;
        while ((f = dfs_flow(source_node, INF)) > 0) flow += f;
    }
    return flow;
}

int solve_system() {
    grid[zr][zc] = 0;
    construct_adjacency();
    spfa_compute();
    grid[zr][zc] = -1;
    construct_adjacency();
    floyd_warshall();
    initialize_flow_network();
    return dinic_maxflow();
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> N >> TIME_LIMIT;
    sources.clear();
    destinations.clear();
    memset(grid, 0, sizeof(grid));

    for (int i = 1; i <= N; ++i) {
        cin >> current_line;
        for (int j = 0; j < N; ++j) {
            if (current_line[j] == 'Y') grid[i][j+1] = -1;
            else if (current_line[j] == 'Z') {
                zr = i; zc = j+1;
                grid[i][j+1] = -1;
            }
            else if (current_line[j] > '0' && current_line[j] <= '9') {
                sources.push_back(i);
                sources.push_back(j+1);
                sources.push_back(current_line[j] - '0');
            }
        }
    }

    for (int i = 1; i <= N; ++i) {
        cin >> current_line;
        for (int j = 0; j < N; ++j) {
            if (current_line[j] > '0' && current_line[j] <= '9') {
                destinations.push_back(i);
                destinations.push_back(j+1);
                destinations.push_back(current_line[j] - '0');
            }
        }
    }

    cout << solve_system() << '\n';
    return 0;
}
